        >>> print(v1.constraintMask)
        [ True False False False]
        >>> print(v1)
        [ 1.  0.  0.  0.]
        >>> v1.constrain(3., where=(x > 1) & (y > 1))
        >>> print(v1.constraintMask)
        [ True False False  True]
        >>> print(v1)
